/**
 * Watch targets for promote-lights demo mode.
 *
 * `/lights watch <target>` (or PROMOTE_LIGHTS_WATCH=<target>) tracks any open
 * PR in any repo, so the band can be shown without a live promote PR.
 * Accepted target forms:
 * - owner/repo#123
 * - owner/repo 123
 * - https://github.com/owner/repo/pull/123
 */

export interface WatchTarget {
  owner: string;
  repo: string;
  number: number;
}

const NAME = "[A-Za-z0-9_.-]+";
const HASH_FORM = new RegExp(`^(${NAME})/(${NAME})#(\\d+)$`);
const SPACE_FORM = new RegExp(`^(${NAME})/(${NAME})\\s+#?(\\d+)$`);
const URL_FORM = new RegExp(`^https?://github\\.com/(${NAME})/(${NAME})/pull/(\\d+)(?:[/?#].*)?$`);

export function parseWatchTarget(input: string | undefined | null): WatchTarget | null {
  const text = (input ?? "").trim();
  if (!text) return null;
  for (const form of [HASH_FORM, SPACE_FORM, URL_FORM]) {
    const m = form.exec(text);
    if (m) {
      const number = Number(m[3]);
      if (!Number.isSafeInteger(number) || number <= 0) return null;
      return { owner: m[1], repo: m[2], number };
    }
  }
  return null;
}

export function formatWatchTarget(t: WatchTarget): string {
  return `${t.owner}/${t.repo}#${t.number}`;
}

/**
 * Every distinct check-run name on a head, in first-seen order. Used when the
 * watched repo protects nothing: the lights then cover every check that ran,
 * and matchAndClassify still takes the worst run per name.
 */
export function allCheckNames(runs: ReadonlyArray<{ name: string }>): string[] {
  const seen = new Set<string>();
  const names: string[] = [];
  for (const r of runs) {
    if (!seen.has(r.name)) {
      seen.add(r.name);
      names.push(r.name);
    }
  }
  return names;
}

export const WATCH_USAGE = "usage: /lights watch owner/repo#123 (or owner/repo 123, or a PR URL)";
export const NO_PR_HINT = "no promote PR open; try /lights watch owner/repo#123 to show lights for any open PR";
